# owner: platform
from hourglass.models import Span

def _check_step(step):
    if step <= 0 or 60 % step:
        raise ValueError(f"step must divide an hour evenly: {step}")

def _snap(value, step):
    return (value + step // 2) // step * step

def _clock(value):
    return f"{value // 60:02d}:{value % 60:02d}"

def round_labels(spans, step):
    """Snap each span to the nearest step and label it like 09:00-17:15 (8h 15m)."""
    _check_step(step)
    labels = []
    for span in spans:
        snapped = Span(_snap(span.start, step), _snap(span.end, step))
        hours, mins = divmod(snapped.minutes, 60)
        labels.append(f"{_clock(snapped.start)}-{_clock(snapped.end)} ({hours}h {mins}m)")
    return labels
